(function(root){'use strict';
const kinds=new Set(['stages','wall','wall-recommend','giant','pressure','clara-stacks','recommend','positions','dealer-tier','optimize','compose']);
const finals={stages:'stage-result',wall:'wall','wall-recommend':'wall-recommend',giant:'giant',pressure:'pressure-result','clara-stacks':'clara-result',recommend:['recommended','recommend'],positions:'positions','dealer-tier':'dealer-results',optimize:'optimized',compose:'composed'};
// Tagged values preserve the structured-clone values used by simulation results.
function pack(value){if(value===undefined)return['u'];if(typeof value==='number'&&!Number.isFinite(value))return['n',String(value)];if(value instanceof Map)return['m',[...value].map(([k,v])=>[pack(k),pack(v)])];if(value instanceof Set)return['s',[...value].map(pack)];if(Array.isArray(value))return['a',value.map(pack)];if(value&&typeof value==='object')return['o',Object.keys(value).sort().map(k=>[k,pack(value[k])])];return['v',value];}
function unpack(value){const [tag,data]=value;if(tag==='u')return undefined;if(tag==='n')return Number(data);if(tag==='a')return data.map(unpack);if(tag==='m')return new Map(data.map(([k,v])=>[unpack(k),unpack(v)]));if(tag==='s')return new Set(data.map(unpack));if(tag==='o')return Object.fromEntries(data.map(([k,v])=>[k,unpack(v)]));if(tag==='v')return data;throw Error('Invalid shared result');}
function complete(kind,result){if(!result||result.error||result.partial||result.refreshing||![].concat(finals[kind]||[]).includes(result.kind))return false;const array=k=>Array.isArray(result[k]),object=k=>!!result[k]&&typeof result[k]==='object'&&!Array.isArray(result[k]);switch(kind){case 'stages':return array('reports');case 'wall':return object('result');case 'wall-recommend':return array('cells')&&array('replays');case 'giant':return object('giant');case 'pressure':return object('before');case 'clara-stacks':return array('rows');case 'recommend':return result.kind==='recommended'?object('build')&&object('result'):array('gems');case 'positions':return array('results');case 'dealer-tier':return array('rows');case 'optimize':case 'compose':return array('cells')&&array('marks')&&object('result');default:return false;}}
function identity(url,input,revision){const {id,cacheToken,force,...conditions}=input;if(input.kind==='compose'){delete conditions.searchSeed;delete conditions.resumeLayout;}return{revision,worker:new URL(url,'https://local.invalid').pathname,conditions};}
class SharedResults{
 constructor({revision,fetch:request=root.fetch?.bind(root),crypto=root.crypto,timeout=2500}={}){this.revision=revision;this.fetch=request;this.crypto=crypto;this.timeout=timeout;}
 supports(job){return /^[a-f0-9]{64}$/.test(this.revision||'')&&!!this.fetch&&!!this.crypto?.subtle&&kinds.has(job.data?.kind);}
 async key(job){return Array.from(new Uint8Array(await this.crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(pack(identity(job.url,job.data,this.revision)))))),v=>v.toString(16).padStart(2,'0')).join('');}
 async request(url,options){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),this.timeout);try{const response=await this.fetch(url,{...options,signal:controller.signal});return response.ok?await response.json():null;}catch{return null;}finally{clearTimeout(timer);}}
 async lookup(job){if(job.data.force||job.data.resumeLayout)return null;const key=await this.key(job),row=await this.request('/api/calculation-results?revision='+this.revision+'&key='+key+'&kind='+job.data.kind);if(row?.revision!==this.revision||!row.result)return null;try{const result=unpack(row.result);return complete(job.data.kind,result)?{...result,id:job.data.id,cached:true,cacheSource:'shared-db'}:null;}catch{return null;}}
 async save(job,result){if(!this.supports(job)||!complete(job.data.kind,result)||result.cacheSource==='shared-db')return false;const {id,cached,cacheSource,...output}=result,key=await this.key(job),body=JSON.stringify({kind:job.data.kind,result:pack(output)});if(new TextEncoder().encode(body).length>1572864)return false;const response=await this.request('/api/calculation-results?revision='+this.revision+'&key='+key+'&kind='+job.data.kind,{method:'PUT',headers:{'Content-Type':'application/json'},body});return !!response?.saved;}
}
root.CoopSharedResults={SharedResults,pack,unpack,identity,complete};if(typeof module!=='undefined')module.exports=root.CoopSharedResults;
})(typeof globalThis!=='undefined'?globalThis:this);
